using System;
using UnityEngine;

namespace ESP.Presentation.Editor
{
    /// <summary>Run in the project VM with -executeMethod ESP.Presentation.Editor.CloudBlendChecks.Validate.</summary>
    public static class CloudBlendChecks
    {
        const int Width = 64, Height = 32, Count = Width * Height;
        static readonly Color32 Missing = new Color32(0, 0, 0, 0);
        // Fixed samples from the NASA MODIS_Cloud_Fraction palette, not generated by
        // the decoder under test: measured 0%, 50%, and 100% cloud fraction.
        static readonly Color32 Clear = new Color32(102, 0, 119, 255);
        static readonly Color32 Half = new Color32(0, 220, 0, 255);
        static readonly Color32 Full = new Color32(255, 0, 5, 255);

        public static void Validate()
        {
            ConstantField();
            ClearAndMissing();
            MissingAndInvalid();
            LongitudeWrapAndBoundedSupport();
            PolarConsistency();
            DateWeights();
            Debug.Log("ESP_CLOUD_BLEND_CHECKS_OK constant clear missing invalid longitude poles dateWeights");
        }

        static void ConstantField()
        {
            var blend = NewBlend(); var observed = new bool[Count];
            Require(blend.Add(Filled(Half), 0, observed, out int unknown) == Count && unknown == 0,
                "Constant valid field must decode every sample.");
            var result = blend.Finish();
            for (int i = 0; i < Count; i++)
            {
                Require(observed[i] && result[i].g == 255, "Full observation support must survive filtering.");
                Near(Fraction(result[i]), .5f, .005f, "Constant fraction changed under spherical filtering.");
            }
        }

        static void ClearAndMissing()
        {
            var source = Filled(Missing); var observed = new bool[Count]; var blend = NewBlend();
            for (int y = 0; y < Height; y++)
            for (int x = 0; x < Width / 2; x++) source[y * Width + x] = Clear;
            Require(blend.Add(source, 0, observed, out int unknown) == Count / 2 && unknown == 0,
                "Measured clear sky must count as valid, not missing.");
            var result = blend.Finish(); int observedCount = 0;
            for (int i = 0; i < Count; i++)
            {
                if (observed[i]) observedCount++;
                Require(result[i].r == 0, "Clear observations must not acquire clouds through filtering.");
            }
            Require(observedCount == Count / 2, "Interpolation must not mark new pixels as observed.");
            Require(result[(Height / 2) * Width + Width / 4].g == 255,
                "Interior clear observation must retain full support.");
            Require(result[(Height / 2) * Width + 3 * Width / 4].g == 0,
                "A broad unobserved region must retain zero support.");
        }

        static void MissingAndInvalid()
        {
            var source = Filled(Missing); var observed = new bool[Count]; var blend = NewBlend();
            source[0] = new Color32(192, 192, 192, 255); // Explicit NASA fill, never cloud.
            source[1] = new Color32(254, 17, 33, 255); // Unknown non-palette RGB.
            Require(blend.Add(source, 0, observed, out int unknown) == 0 && unknown == 1,
                "Fill must be missing; unknown opaque RGB must be reported.");
            foreach (Color32 pixel in blend.Finish())
                Require(pixel.r == 0 && pixel.g == 0, "Unobserved field must have zero density and support.");
            foreach (bool valid in observed) Require(!valid, "Invalid colors must never become observations.");
        }

        static void LongitudeWrapAndBoundedSupport()
        {
            var source = Filled(Missing); var blend = NewBlend(); var observed = new bool[Count];
            for (int y = 0; y < Height; y++)
            {
                source[y * Width] = Full;
                source[y * Width + Width - 1] = Full;
            }
            blend.Add(source, 0, observed, out _);
            var result = blend.Finish(); int row = (Height / 2) * Width;
            for (int x = 0; x < 6; x++)
            {
                Near(result[row + x].g, result[row + Width - 1 - x].g, 1,
                    "Equivalent distances across the antimeridian must have equal support.");
                if (result[row + x].g > 0)
                    Near(Fraction(result[row + x]), 1, .005f,
                        "Missing neighbors must not darken a valid 100% cloud fraction.");
            }
            Require(result[row].g > 0 && result[row + Width - 1].g > 0,
                "Cloud observation must remain visible on both sides of the seam.");
            Require(result[row + 1].g > 0 && !observed[row + 1],
                "Nearby display interpolation must not alter original observation provenance.");
            Require(result[row + Width / 2].g == 0, "Filtering must not fill a large remote gap.");
        }

        static void PolarConsistency()
        {
            var source = Filled(Missing); var blend = NewBlend();
            for (int x = 0; x < Width / 2; x++)
            {
                source[x] = Half;
                source[(Height - 1) * Width + x] = Full;
            }
            blend.Add(source, 0, new bool[Count], out _);
            var result = blend.Finish();
            foreach (int row in new[] { 0, (Height - 1) * Width })
            {
                Require(result[row].g > 0, "A sampled polar ring must retain nonzero support.");
                for (int x = 1; x < Width; x++)
                    Require(result[row + x].r == result[row].r && result[row + x].g == result[row].g,
                        "Every UV longitude at a pole must meet with the same value.");
            }
            Near(Fraction(result[0]), .5f, .04f, "South polar interpolation corrupted constant fraction.");
            Near(Fraction(result[(Height - 1) * Width]), 1, .005f,
                "North polar interpolation corrupted constant fraction.");
        }

        static void DateWeights()
        {
            var blend = NewBlend(); var observed = new bool[Count];
            blend.Add(Filled(Clear), 0, observed, out _);
            blend.Add(Filled(Half), 1, observed, out _);
            blend.Add(Filled(Full), 2, observed, out _);
            float expected = (.5f * .65f + .4225f) / (1 + .65f + .4225f);
            foreach (Color32 pixel in blend.Finish())
                Near(Fraction(pixel), expected, .005f,
                    "Temporal composite must be the dated weighted mean, not latest winner or maximum.");
            var reverse = NewBlend();
            reverse.Add(Filled(Full), 2, new bool[Count], out _);
            reverse.Add(Filled(Half), 1, new bool[Count], out _);
            reverse.Add(Filled(Clear), 0, new bool[Count], out _);
            Near(Fraction(reverse.Finish()[Count / 2]), expected, .005f,
                "Date weights must depend on date age, not insertion order.");
        }

        static CloudShell.ObservationBlend NewBlend() => new CloudShell.ObservationBlend(Width, Height);
        static Color32[] Filled(Color32 value)
        {
            var result = new Color32[Count];
            for (int i = 0; i < result.Length; i++) result[i] = value;
            return result;
        }
        static float Fraction(Color32 pixel) => pixel.g > 0 ? pixel.r / (float)pixel.g : 0;
        static void Near(float actual, float expected, float tolerance, string message)
            => Require(Mathf.Abs(actual - expected) <= tolerance, message + " actual=" + actual + " expected=" + expected);
        static void Require(bool condition, string message)
        {
            if (!condition) throw new InvalidOperationException("ESP cloud blend check: " + message);
        }
    }
}
